package schema_test

// Replays Pi's results over a seeded corpus of schemas and loosely typed values: for every value, what coerce() and parse() of `compile(schema, { formats, coerce: true })` returned in packages/schema at Pi commit b556cfe5 (the coerced value with every object's member order and the sign of every zero, whether coerce() returned its input itself, and parse()'s result).
// testdata/coerce-golden.json is generated by testdata/gen-coerce-golden.mjs under Node 24 against a Pi export of packages/schema: `node gen-coerce-golden.mjs <pi>/packages/schema coerce-golden.json b556cfe5`. The corpus is seeded (mulberry32), so the file is reproducible.

import (
	"fmt"
	"reflect"
	"testing"

	"github.com/MichaelKinsy/PiG/schema"
	"github.com/MichaelKinsy/PiG/schema/formats"
)

// sameReference is JavaScript's Object.is for a coerced value and its input: primitives by value, objects and arrays by reference.
func sameReference(a, b any) bool {
	switch x := a.(type) {
	case *schema.Object:
		y, ok := b.(*schema.Object)
		return ok && x == y
	case map[string]any:
		y, ok := b.(map[string]any)
		return ok && reflect.ValueOf(x).Pointer() == reflect.ValueOf(y).Pointer()
	case []any:
		y, ok := b.([]any)
		return ok && len(x) == len(y) && (len(x) == 0 || &x[0] == &y[0])
	}
	return exactJSON(a, b)
}

func TestCoerceMatchesPi(t *testing.T) {
	golden := readJSON(t, "testdata/coerce-golden.json").(*schema.Object)
	pristine := readJSON(t, "testdata/coerce-golden.json").(*schema.Object)
	if golden.Value("piCommit") != "b556cfe5" || golden.Value("thrown") != float64(0) {
		t.Fatalf("golden is from %v and holds %v values Pi threw for", golden.Value("piCommit"), golden.Value("thrown"))
	}
	cases := golden.Value("cases").([]any)
	pristineCases := pristine.Value("cases").([]any)
	values, changed, parsedOK := 0, 0, 0
	for i, c := range cases {
		tc := c.(*schema.Object)
		options := tc.Value("options").(*schema.Object)
		opts := schema.CompileOptions{Formats: formats.Formats()}
		if draft, ok := options.Value("draft").(string); ok {
			opts.Draft = schema.Draft(draft)
		}
		if reject, ok := options.Value("unresolvedRefs").(string); ok {
			opts.UnresolvedRefs = schema.UnresolvedRefs(reject)
		}
		validator, err := schema.CompileCoercing(tc.Value("schema"), opts)
		if err != nil {
			t.Fatalf("case %d: CompileCoercing(%s): %v", i, marshalled(tc.Value("schema")), err)
		}
		for j, v := range tc.Value("values").([]any) {
			values++
			want := v.(*schema.Object)
			input := want.Value("input")
			name := fmt.Sprintf("case %d value %d", i, j)
			if note, ok := tc.Value("note").(string); ok {
				name += " (" + note + ")"
			}
			coerced, err := validator.Coerce(input)
			if err != nil {
				t.Fatalf("%s: Coerce(%s): %v", name, marshalled(input), err)
			}
			if !exactJSON(coerced, want.Value("coerced")) {
				t.Fatalf("%s: schema %s\ninput   %s\ncoerced %s\nPi      %s", name, marshalled(tc.Value("schema")), marshalled(input), marshalled(coerced), marshalled(want.Value("coerced")))
			}
			if got, pi := sameReference(coerced, input), want.Value("same").(bool); got != pi {
				t.Fatalf("%s: schema %s\ninput %s: coerce returned its input itself = %v, Pi %v", name, marshalled(tc.Value("schema")), marshalled(input), got, pi)
			}
			pristineInput := pristineCases[i].(*schema.Object).Value("values").([]any)[j].(*schema.Object).Value("input")
			if !exactJSON(input, pristineInput) {
				t.Fatalf("%s: Coerce modified its input: %s, was %s", name, marshalled(input), marshalled(pristineInput))
			}
			if !sameReference(coerced, input) {
				changed++
			}

			// A failing parse explains the coerced value (the explanation is not the coercion's: Pi's golden does not hold its errors); a succeeding one returns the coerced value.
			wantParse := want.Value("parse").(*schema.Object)
			valid := checkOf(t, validator, coerced)
			if valid != wantParse.Value("ok").(bool) {
				t.Fatalf("%s: schema %s\ninput %s: the coerced value is valid = %v, Pi's parse ok = %v", name, marshalled(tc.Value("schema")), marshalled(input), valid, !valid)
			}
			if !valid {
				continue
			}
			parsedOK++
			result := parseOf(t, validator, input)
			if !result.OK || !exactJSON(result.Value, wantParse.Value("value")) {
				t.Fatalf("%s: parse = %+v, Pi %s", name, result, marshalled(wantParse.Value("value")))
			}
		}
	}
	if values < 3000 || changed < 800 || parsedOK < 1000 {
		t.Fatalf("the corpus is too thin to compare: %d values, %d coerced, %d parsed ok", values, changed, parsedOK)
	}
	t.Logf("%d schemas, %d values (%d coerced, %d parsed ok)", len(cases), values, changed, parsedOK)
}
